// Sweep the consumer count with the same rules as the live view, and measure.
// The simulation, one second at a time. Shared rules (the sweep cell uses the same):
// 12 keys with skewed traffic, partition = hash(key) % P, consumers share partitions
// round-robin, each consumer handles `speed` messages a second across its partitions,
// and consumer 0 crashes at 90 s; its partitions wait 10 s for the group to rebalance.
var KEYS = ['ACME', 'BOLT', 'CRUX', 'DYNO', 'EPIC', 'FLUX', 'GRID', 'HALO', 'IONX', 'JADE', 'KITE', 'LUME'];
var WEIGHTS = [30, 18, 12, 9, 7, 6, 5, 4, 3, 2, 2, 2];     // % of the traffic: a few keys are hot
function hash(s) { var h = 2166136261; for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h; }
function simulate(P, C, rate, speed, seconds) {
  var share = new Array(P).fill(0);
  KEYS.forEach(function (k, i) { share[hash(k) % P] += WEIGHTS[i] / 100; });
  var end = new Array(P).fill(0), done = new Array(P).fill(0), timeline = [];
  var alive = [], crashAt = 90, rebalanceAt = 100;
  for (var c = 0; c < C; c++) alive.push(c);
  for (var t = 1; t <= seconds; t++) {
    var burst = t > 40 && t <= 60 ? 3 : 1;            // a 20-second burst at 3x
    for (var p = 0; p < P; p++) end[p] += rate * burst * share[p];
    var group = t > rebalanceAt && C > 1 ? alive.slice(1) : alive;
    var owner = [];
    for (p = 0; p < P; p++) owner.push(group[p % group.length]);
    for (c = 0; c < C; c++) {
      if (c === 0 && t > crashAt && t <= rebalanceAt && C > 1) continue;   // crashed, not yet noticed
      if (c === 0 && t > rebalanceAt && C > 1) continue;                   // gone
      var mine = [];
      for (p = 0; p < P; p++) if (owner[p] === c) mine.push(p);
      var budget = speed;
      // share this consumer's capacity across its partitions, most behind first
      mine.sort(function (a, b) { return (end[b] - done[b]) - (end[a] - done[a]); });
      mine.forEach(function (p, i) {
        var fair = budget / (mine.length - i), take = Math.min(fair, end[p] - done[p]);
        done[p] += take; budget -= take;
      });
    }
    timeline.push({ t: t, lag: end.map(function (e, p) { return e - done[p]; }), owner: owner.slice(),
      crashed: C > 1 && t > crashAt && t <= rebalanceAt });
  }
  return { share: share, timeline: timeline };
}

const P = Math.round(nb.get('kf_partitions') ?? 6), rate = nb.get('kf_rate') ?? 600, speed = nb.get('kf_speed') ?? 300;
const rows = [];
console.log('partitions ' + P + ', ' + rate + ' msg/s (3x for 20 s), ' + speed + ' msg/s per consumer\n');
console.log('consumers  peak lag   lag at 180 s   caught up after the burst at');
for (let C = 1; C <= 12; C++) {
  const run = simulate(P, C, rate, speed, 180);
  const totals = run.timeline.map(x => x.lag.reduce((a, b) => a + b, 0));
  const peak = Math.max(...totals), final = totals.at(-1);
  // caught up = less than one second of traffic waiting, after the burst ends at 60 s
  const back = totals.findIndex((v, i) => i >= 60 && v < rate);
  rows.push({ consumers: C, value: peak, what: 'peak lag' }, { consumers: C, value: final, what: 'lag at 180 s' });
  console.log(String(C).padStart(9) + Math.round(peak).toLocaleString().padStart(10) + Math.round(final).toLocaleString().padStart(15) +
    (back < 0 ? 'never' : (back + 1) + ' s').padStart(31));
}
const share = simulate(P, 1, rate, speed, 1).share;
console.log('\nkey shares by partition: ' + share.map((s, p) => p + ': ' + Math.round(s * 100) + '%').join(', '));
console.log('busiest partition: ' + Math.round(Math.max(...share) * rate) + ' msg/s, against ' + speed + ' msg/s for one consumer');
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Adding consumers to a group with ' + P + ' partitions',
  data: { values: rows },
  mark: { type: 'line', point: true },
  encoding: {
    x: { field: 'consumers', type: 'quantitative', axis: { tickMinStep: 1 } },
    y: { field: 'value', type: 'quantitative', title: 'messages waiting' },
    color: { field: 'what', type: 'nominal', title: null },
  },
};
